  1: /*
  2:  * VelaWear Agent - BLE service
  3:  *
  4:  * Service contract:
  5:  *   status     READ + NOTIFY: [motion_type, intensity_percent, alert]
  6:  *   threshold  READ + WRITE:  uint16 little-endian seconds
  7:  */
  8: 
  9: #include <nuttx/config.h>
 10: 
 11: #include <errno.h>
 12: #include <stdbool.h>
 13: #include <stdint.h>
 14: #include <stdio.h>
 15: #include <string.h>
 16: #include <syslog.h>
 17: 
 18: #include <zephyr/kernel.h>
 19: #include <zephyr/bluetooth/bluetooth.h>
 20: #include <zephyr/bluetooth/gatt.h>
 21: #include <zephyr/bluetooth/gap.h>
 22: #include <zephyr/bluetooth/uuid.h>
 23: 
 24: #include "velawear_ble.h"
 25: 
 26: #define VELAWEAR_BLE_SERVICE_UUID \
 27:   BT_UUID_DECLARE_128(0x12345678, 0x9abc, 0xdef0, 0x1234, 0x56789abcdef0)
 28: 
 29: #define VELAWEAR_BLE_STATUS_UUID \
 30:   BT_UUID_DECLARE_128(0x12345679, 0x9abc, 0xdef0, 0x1234, 0x56789abcdef0)
 31: 
 32: #define VELAWEAR_BLE_THRESHOLD_UUID \
 33:   BT_UUID_DECLARE_128(0x1234567a, 0x9abc, 0xdef0, 0x1234, 0x56789abcdef0)
 34: 
 35: static velawear_config_t *g_config;
 36: static pthread_mutex_t g_lock;
 37: static bool g_initialized;
 38: static bool g_alert_active;
 39: static int g_motion_type;
 40: static uint8_t g_intensity_percent;
 41: 
 42: static ssize_t velawear_ble_read_status(struct bt_conn *conn,
 43:                                         const struct bt_gatt_attr *attr,
 44:                                         void *buf, uint16_t len,
 45:                                         uint16_t offset)
 46: {
 47:   uint8_t value[3];
 48: 
 49:   (void)attr;
 50:   pthread_mutex_lock(&g_lock);
 51:   value[0] = (uint8_t)g_motion_type;
 52:   value[1] = g_intensity_percent;
 53:   value[2] = g_alert_active ? 1 : 0;
 54:   pthread_mutex_unlock(&g_lock);
 55: 
 56:   return bt_gatt_attr_read(conn, attr, buf, len, offset,
 57:                            value, sizeof(value));
 58: }
 59: 
 60: static ssize_t velawear_ble_read_threshold(struct bt_conn *conn,
 61:                                            const struct bt_gatt_attr *attr,
 62:                                            void *buf, uint16_t len,
 63:                                            uint16_t offset)
 64: {
 65:   uint16_t seconds;
 66: 
 67:   (void)attr;
 68:   pthread_mutex_lock(&g_lock);
 69:   seconds = (uint16_t)g_config->sedentary_threshold_sec;
 70:   pthread_mutex_unlock(&g_lock);
 71: 
 72:   return bt_gatt_attr_read(conn, attr, buf, len, offset,
 73:                            &seconds, sizeof(seconds));
 74: }
 75: 
 76: static ssize_t velawear_ble_write_threshold(struct bt_conn *conn,
 77:                                             const struct bt_gatt_attr *attr,
 78:                                             const void *buf, uint16_t len,
 79:                                             uint16_t offset, uint8_t flags)
 80: {
 81:   const uint8_t *data = (const uint8_t *)buf;
 82:   uint16_t seconds;
 83: 
 84:   (void)conn;
 85:   (void)attr;
 86:   if (buf == NULL || offset != 0 || len != sizeof(uint16_t) ||
 87:       (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0)
 88:     {
 89:       return -EINVAL;
 90:     }
 91: 
 92:   seconds = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
 93:   if (seconds < 10 || seconds > 3600)
 94:     {
 95:       return -EINVAL;
 96:     }
 97: 
 98:   pthread_mutex_lock(&g_lock);
 99:   g_config->sedentary_threshold_sec = seconds;
100:   pthread_mutex_unlock(&g_lock);
101:   syslog(LOG_INFO, "[BLE] Sedentary threshold updated: %u s\n",
102:          (unsigned int)seconds);
103:   return len;
104: }
105: 
106: static void velawear_ble_status_ccc_changed(const struct bt_gatt_attr *attr,
107:                                             uint16_t value)
108: {
109:   (void)attr;
110:   syslog(LOG_INFO, "[BLE] Status notifications %s\n",
111:          (value == BT_GATT_CCC_NOTIFY) ? "enabled" : "disabled");
112: }
113: 
114: /* Static registration is performed by the Zblue host during bt_enable(). */
115: BT_GATT_SERVICE_DEFINE(velawear_svc,
116:   BT_GATT_PRIMARY_SERVICE(VELAWEAR_BLE_SERVICE_UUID),
117:   BT_GATT_CHARACTERISTIC(VELAWEAR_BLE_STATUS_UUID,
118:                          BT_GATT_CHRC_READ | BT_GATT_CHRC_NOTIFY,
119:                          BT_GATT_PERM_READ,
120:                          velawear_ble_read_status, NULL, NULL),
121:   BT_GATT_CCC(velawear_ble_status_ccc_changed,
122:               BT_GATT_PERM_READ | BT_GATT_PERM_WRITE),
123:   BT_GATT_CHARACTERISTIC(VELAWEAR_BLE_THRESHOLD_UUID,
124:                          BT_GATT_CHRC_READ | BT_GATT_CHRC_WRITE,
125:                          BT_GATT_PERM_READ | BT_GATT_PERM_WRITE,
126:                          velawear_ble_read_threshold,
127:                          velawear_ble_write_threshold, NULL)
128: );
129: 
130: static const struct bt_data g_advertising_data[] =
131: {
132:   BT_DATA_BYTES(BT_DATA_FLAGS, BT_LE_AD_GENERAL | BT_LE_AD_NO_BREDR),
133:   BT_DATA_BYTES(BT_DATA_UUID128_ALL,
134:                 BT_UUID_128_ENCODE(0x12345678, 0x9abc, 0xdef0,
135:                                    0x1234, 0x56789abcdef0)),
136: };
137: 
138: static const struct bt_data g_scan_response_data[] =
139: {
140:   BT_DATA(BT_DATA_NAME_COMPLETE, "VelaWear", sizeof("VelaWear") - 1),
141: };
142: 
143: int velawear_ble_init(velawear_config_t *config)
144: {
145:   int ret;
146: 
147:   if (config == NULL)
148:     {
149:       return VELAWEAR_ERR_INVAL;
150:     }
151: 
152:   g_config = config;
153:   ret = pthread_mutex_init(&g_lock, NULL);
154:   if (ret != 0)
155:     {
156:       g_config = NULL;
157:       return -ret;
158:     }
159: 
160:   g_alert_active = false;
161:   g_motion_type = 0;
162:   g_intensity_percent = 0;
163: 
164:   ret = bt_enable(NULL);
165:   if (ret < 0)
166:     {
167:       pthread_mutex_destroy(&g_lock);
168:       g_config = NULL;
169:       syslog(LOG_WARNING, "[BLE] Bluetooth init failed: %d\n", ret);
170:       return ret;
171:     }
172: 
173:   ret = bt_le_adv_start(BT_LE_ADV_CONN_FAST_1,
174:                         g_advertising_data, ARRAY_SIZE(g_advertising_data),
175:                         g_scan_response_data, ARRAY_SIZE(g_scan_response_data));
176:   if (ret < 0)
177:     {
178:       pthread_mutex_destroy(&g_lock);
179:       g_config = NULL;
180:       syslog(LOG_WARNING, "[BLE] Advertising start failed: %d\n", ret);
181:       return ret;
182:     }
183: 
184:   g_initialized = true;
185:   syslog(LOG_INFO, "[BLE] VelaWear GATT service registered; advertising\n");
186:   return VELAWEAR_OK;
187: }
188: 
189: void velawear_ble_cleanup(void)
190: {
191:   if (!g_initialized)
192:     {
193:       return;
194:     }
195: 
196:   g_initialized = false;
197:   pthread_mutex_destroy(&g_lock);
198:   g_config = NULL;
199: }
200: 
201: void velawear_ble_update_motion(int motion_type, float intensity)
202: {
203:   uint8_t value[3];
204: 
205:   if (!g_initialized)
206:     {
207:       return;
208:     }
209: 
210:   if (intensity < 0.0f)
211:     {
212:       intensity = 0.0f;
213:     }
214:   if (intensity > 1.0f)
215:     {
216:       intensity = 1.0f;
217:     }
218: 
219:   pthread_mutex_lock(&g_lock);
220:   g_motion_type = motion_type;
221:   g_intensity_percent = (uint8_t)(intensity * 100.0f);
222:   value[0] = (uint8_t)g_motion_type;
223:   value[1] = g_intensity_percent;
224:   value[2] = g_alert_active ? 1 : 0;
225:   pthread_mutex_unlock(&g_lock);
226: 
227:   (void)bt_gatt_notify(NULL, &attr_velawear_svc[2], value, sizeof(value));
228: }
229: 
230: void velawear_ble_set_alert(bool active)
231: {
232:   uint8_t value[3];
233: 
234:   if (!g_initialized)
235:     {
236:       return;
237:     }
238: 
239:   pthread_mutex_lock(&g_lock);
240:   g_alert_active = active;
241:   value[0] = (uint8_t)g_motion_type;
242:   value[1] = g_intensity_percent;
243:   value[2] = g_alert_active ? 1 : 0;
244:   pthread_mutex_unlock(&g_lock);
245: 
246:   (void)bt_gatt_notify(NULL, &attr_velawear_svc[2], value, sizeof(value));
247: }

