289: static ssize_t velawear_ble_write_llm_response(
290:     struct bt_conn *conn, const struct bt_gatt_attr *attr, const void *buf,
291:     uint16_t len, uint16_t offset, uint8_t flags)
292: {
293:   velawear_agent_llm_response_t response;
294: 
295:   (void)conn;
296:   (void)attr;
297:   if (buf == NULL || offset != 0 ||
298:       (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0 ||
299:       velawear_agent_decode_llm_response((const uint8_t *)buf, len,
300:                                          &response) < 0)
301:     {
302:       return -EINVAL;
303:     }
304: 
305:   pthread_mutex_lock(&g_lock);
306:   if (!g_initialized || !g_llm_waiting ||
307:       response.sequence != g_llm_pending_sequence)
308:     {
309:       pthread_mutex_unlock(&g_lock);
310:       return -EALREADY;
311:     }
312: 
313:   g_llm_response_status = response.status;
314:   g_llm_response_length = response.length;
315:   memcpy(g_llm_response_text, response.text,
316:          sizeof(g_llm_response_text));
317:   g_llm_waiting = false;
318:   pthread_mutex_unlock(&g_lock);
319: 
320:   k_sem_give(&g_llm_response_sem);
321:   syslog(LOG_INFO, "[BLE] LLM response accepted: seq=%u status=%u bytes=%u\n",
322:          (unsigned int)response.sequence, (unsigned int)response.status,
323:          (unsigned int)response.length);
324:   return len;
325: }
