327: static ssize_t velawear_ble_write_agent_command(
328:     struct bt_conn *conn, const struct bt_gatt_attr *attr, const void *buf,
329:     uint16_t len, uint16_t offset, uint8_t flags)
330: {
331:   const uint8_t *data = (const uint8_t *)buf;
332:   velawear_agent_command_t command;
333:   velawear_event_t event;
334:   int ret;
335: 
336:   (void)conn;
337:   (void)attr;
338:   if (buf == NULL || offset != 0 ||
339:       (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0 ||
340:       velawear_agent_decode_command(data, len, &command) < 0)
341:     {
342:       return -EINVAL;
343:     }
344: 
345:   pthread_mutex_lock(&g_lock);
346:   if (g_events == NULL ||
347:       (g_have_last_agent_command_sequence &&
348:        !velawear_agent_command_sequence_is_newer(
349:            command.sequence, g_last_agent_command_sequence)))
350:     {
351:       pthread_mutex_unlock(&g_lock);
352:       return -EALREADY;
353:     }
354: 
355:   g_last_agent_command_sequence = command.sequence;
356:   g_have_last_agent_command_sequence = true;
357:   pthread_mutex_unlock(&g_lock);
358: 
359:   memset(&event, 0, sizeof(event));
360:   event.type = VELAWEAR_EVENT_BLE_MSG;
361:   event.priority = VELAWEAR_PRIORITY_HIGH;
362:   event.data.ble.length = len;
363:   memcpy(event.data.ble.data, data, len);
364:   ret = event_manager_push(g_events, &event);
365:   if (ret < 0)
366:     {
367:       syslog(LOG_WARNING, "[BLE] Agent command queue full: %d\n", ret);
368:       return BT_GATT_ERR(BT_ATT_ERR_INSUFFICIENT_RESOURCES);
369:     }
370: 
371:   syslog(LOG_INFO, "[BLE] Agent command queued: seq=%u id=%u\n",
372:          (unsigned int)command.sequence, (unsigned int)command.command_id);
373:   return len;
374: }
