376: static ssize_t velawear_ble_write_audio_stream(
377:     struct bt_conn *conn, const struct bt_gatt_attr *attr, const void *buf,
378:     uint16_t len, uint16_t offset, uint8_t flags)
379: {
380:   const uint8_t *data = (const uint8_t *)buf;
381:   int ret;
382: 
383:   (void)conn;
384:   (void)attr;
385:   if (buf == NULL || offset != 0 || len < 2 ||
386:       (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0)
387:     {
388:       return -EINVAL;
389:     }
390: 
391:   switch (data[1])
392:     {
393:       case VELAWEAR_AGENT_AUDIO_START_TYPE:
394:         {
395:           velawear_agent_audio_start_t start;
396: 
397:           if (velawear_agent_decode_audio_start(data, len, &start) < 0)
398:             {
399:               return -EINVAL;
400:             }
401:           ret = velawear_audio_voice_start(start.stream_id,
402:                                            start.sample_count,
403:                                            start.total_bytes,
404:                                            start.crc32);
405:           if (ret == 0)
406:             {
407:               syslog(LOG_INFO,
408:                      "[BLE] Audio stream start: id=%u samples=%lu bytes=%lu\n",
409:                      (unsigned int)start.stream_id,
410:                      (unsigned long)start.sample_count,
411:                      (unsigned long)start.total_bytes);
412:             }
413:         }
414:         break;
415: 
416:       case VELAWEAR_AGENT_AUDIO_DATA_TYPE:
417:         {
418:           velawear_agent_audio_data_t audio_data;
419: 
420:           if (velawear_agent_decode_audio_data(data, len, &audio_data) < 0)
421:             {
422:               return -EINVAL;
423:             }
424:           ret = velawear_audio_voice_write(audio_data.stream_id,
425:                                            audio_data.offset,
426:                                            audio_data.payload,
427:                                            audio_data.payload_length);
428:         }
429:         break;
430: 
431:       case VELAWEAR_AGENT_AUDIO_END_TYPE:
432:         {
433:           velawear_agent_audio_end_t end;
434:           velawear_event_t event;
435:           uint32_t sample_count = 0;
436: 
437:           if (velawear_agent_decode_audio_end(data, len, &end) < 0)
438:             {
439:               return -EINVAL;
440:             }
441:           ret = velawear_audio_voice_end(end.stream_id, end.total_bytes,
442:                                          end.crc32, &sample_count);
443:           if (ret == 0)
444:             {
445:               memset(&event, 0, sizeof(event));
446:               event.type = VELAWEAR_EVENT_VOICE_CMD;
447:               event.priority = VELAWEAR_PRIORITY_NORMAL;
448:               event.timestamp = k_uptime_get_32();
449:               event.data.voice.stream_id = end.stream_id;
450:               event.data.voice.sample_count = sample_count;
451:               ret = event_manager_push(g_events, &event);
452:               if (ret == 0)
453:                 {
454:                   syslog(LOG_INFO,
455:                          "[BLE] Audio stream complete: id=%u samples=%lu\n",
456:                          (unsigned int)end.stream_id,
457:                          (unsigned long)sample_count);
458:                 }
459:               else
460:                 {
461:                   syslog(LOG_WARNING,
462:                          "[BLE] Audio voice event queue failed: %d\n", ret);
463:                 }
464:             }
465:         }
466:         break;
467: 
468:       default:
469:         return -EINVAL;
470:     }
471: 
472:   if (ret < 0)
473:     {
474:       syslog(LOG_WARNING, "[BLE] Audio stream write rejected type=%u: %d\n",
475:              (unsigned int)data[1], ret);
476:       return BT_GATT_ERR(BT_ATT_ERR_UNLIKELY);
477:     }
478: 
479:   return len;
480: }
